import test from 'node:test';
test('Spy verification', (t) => {
  const spy = t.mock.fn((x) => x * 2);
  spy(5);
  assert.equal(spy.mock.callCount(), 1);
  assert.deepEqual(spy.mock.calls[0].arguments, [5]);
});

